<?php
require 'D:/system karas/system end/backend/vendor/autoload.php';$app=require 'D:/system karas/system end/backend/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();use Illuminate\Support\Facades\DB;
$numbers=['E2E-FINAL-MOTORS-20261017-01','E2E-FINAL-CEMENT-20261017-02','E2E-FINAL-STEEL-20261017-03'];$allQty=0;$allValue=0;foreach($numbers as $n){$c=DB::table('containers')->where('container_number',$n)->first();$sum=DB::table('container_lines')->where('container_id',$c->id)->sum('received_quantity');$cost=DB::table('container_costs')->where('container_id',$c->id)->sum('amount_egp');$move=DB::table('inventory_movements')->where('reason','like','%'.$n.'%')->where('movement_type','container_receipt')->first();$moves=$move?DB::table('inventory_movement_lines')->where('inventory_movement_id',$move->id)->count():0;$v=DB::table('container_lines as l')->join('products as p','p.id','=','l.product_id')->where('l.container_id',$c->id)->sum(DB::raw('l.received_quantity * p.purchase_cost_egp'));$allQty+=$sum;$allValue+=$v+$cost;echo "$n | status=$c->status | lines=".DB::table('container_lines')->where('container_id',$c->id)->count()." | qty=$sum | costs=$cost | goods=$v | total=".($v+$cost)." | movement_lines=$moves | warehouse=$c->received_location_id",PHP_EOL;}
echo 'counts containers=',DB::table('containers')->count(),' products=',DB::table('products')->count(),' locations=',DB::table('locations')->count(),' receipts=',DB::table('container_receipts')->count(),' movements=',DB::table('inventory_movements')->count(),' movement_lines=',DB::table('inventory_movement_lines')->count(),PHP_EOL;
echo 'total_qty=', $allQty,' expected_inventory_value=', $allValue,PHP_EOL;
echo 'warehouse_balances=',json_encode(DB::table('inventory_balances as b')->join('locations as l','l.id','=','b.location_id')->select('l.name',DB::raw('SUM(b.quantity_on_hand) as units'),DB::raw('SUM(b.inventory_value_egp) as value'))->groupBy('l.id','l.name')->get(),JSON_UNESCAPED_UNICODE),PHP_EOL;
